 "content": "def transform(grid):
    """Project each side of the solid color-2 rectangle, away from sparse markers."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not cells:
        return out
    r0 = min(r for r, c in cells)
    r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)

    # Along each occupied row, extend each unblocked side to the border.
    for r in range(r0, r1 + 1):
        left_blocked = any(grid[r][c] not in (0, 2) for c in range(c0))
        right_blocked = any(grid[r][c] not in (0, 2) for c in range(c1 + 1, w))
        if not left_blocked:
            for c in range(c0):
                out[r][c] = 2
        if not right_blocked:
            for c in range(c1 + 1, w):
                out[r][c] = 2

    # Along each occupied column, extend each unblocked side to the border.
    for c in range(c0, c1 + 1):
        top_blocked = any(grid[r][c] not in (0, 2) for r in range(r0))
        bottom_blocked = any(grid[r][c] not in (0, 2) for r in range(r1 + 1, h))
        if not top_blocked:
            for r in range(r0):
                out[r][c] = 2
        if not bottom_blocked:
            for r in range(r1 + 1, h):
                out[r][c] = 2
    return out
